//! JPX decoder parity tests against glymur/OpenJPEG fixtures.
//!
//! Fixtures are generated by `tests/gen_jpx_fixtures.py` (system OpenJPEG
//! via glymur — an independent encoder/decoder) and committed. Each `.j2k`
//! is a raw codestream; the matching `.raw` is the reference 8-bit
//! interleaved decode. Reversible coding → pixel-exact parity required.

use pdf_core::parser::jpx;

fn fixture(name: &str) -> (Vec<u8>, Vec<u8>) {
    let base = format!("{}/tests/fixtures/{}", env!("CARGO_MANIFEST_DIR"), name);
    let codestream = std::fs::read(format!("{base}.j2k"))
        .expect("fixture missing — run tests/gen_jpx_fixtures.py");
    let reference = std::fs::read(format!("{base}.raw"))
        .expect("reference missing — run tests/gen_jpx_fixtures.py");
    (codestream, reference)
}

/// Number of differing samples (for diagnostics).
fn diff_count(a: &[u8], b: &[u8]) -> usize {
    a.iter().zip(b.iter()).filter(|(x, y)| x != y).count()
}

#[test]
fn gray_64_matches_reference() {
    let (data, reference) = fixture("jpx_gray_64");
    let img = jpx::decode(&data).expect("decode gray fixture");
    let (w, h, n, pixels) = img.interleaved_u8();
    assert_eq!((w, h, n), (64, 64, 1));
    assert_eq!(
        diff_count(&pixels, &reference),
        0,
        "gray decode differs from OpenJPEG reference"
    );
}

#[test]
fn rgb_64_matches_reference() {
    let (data, reference) = fixture("jpx_rgb_64");
    let img = jpx::decode(&data).expect("decode rgb fixture");
    let (w, h, n, pixels) = img.interleaved_u8();
    assert_eq!((w, h, n), (64, 64, 3));
    assert_eq!(
        diff_count(&pixels, &reference),
        0,
        "rgb (RCT + MCT) decode differs from OpenJPEG reference"
    );
}

#[test]
fn two_tile_gray_matches_reference() {
    let (data, reference) = fixture("jpx_gray_tiles");
    let img = jpx::decode(&data).expect("decode tiled fixture");
    let (w, h, n, pixels) = img.interleaved_u8();
    assert_eq!((w, h, n), (64, 128, 1));
    assert_eq!(
        diff_count(&pixels, &reference),
        0,
        "tiled decode differs from OpenJPEG reference"
    );
}
